def net_revenue(gross, discount):
    if not 0 <= discount <= gross:
        raise ValueError("discount outside gross amount")
    return gross - discount

def mean_or_none(values):
    return sum(values) / len(values) if values else None

assert mean_or_none([0, 10]) == 5

def page_count(rows, size):
    if rows < 0 or size <= 0:
        raise ValueError("invalid pagination inputs")
    return (rows + size - 1) // size

def amount_status(value):
    if value is None:
        return "missing"
    if value < 0:
        return "invalid"
    return "zero" if value == 0 else "valid"

